using PhotoTrail.Windows;
using System.Text.Json;

static class RenameOrderChecks
{
 public static async Task RunAsync(){
  var dates=await VerifiedPhotoDate.InspectAsync(new[]{"2024:01:01 00:00:00Z","2025:01:01 00:00:00Z","2030:01:01 00:00:00Z","2024:01:01 23:00:00+23:00","2024:01:01 00:00:00+24:00"});
  int passed=0;void Check(bool value,string name){if(!value)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
  RenameInput Input(string name,string? tag=null,string? value=null,bool failed=false)=>new(Path.Combine(Path.GetTempPath(),name),tag is null?new Dictionary<string,string>():new Dictionary<string,string>{{tag,value!}},failed){DateResults=dates};
  RenameGroup G(string id,RenameInput input)=>new(id,[input]);
  var groups=new[]{G("ten",Input("file10.jpg","XMP-xmp:Rating","10")),G("two",Input("file2.jpg","XMP-xmp:Rating","2")),G("missing",Input("missing.jpg")),G("tie",Input("file1.jpg","XMP-xmp:Rating","2"))};
  foreach(bool desc in new[]{false,true}){
   var rating=RenameOrder.Ordered(groups,new("rating",desc));Check(rating[^1].Id=="missing","missing-last-"+desc);Check(rating.Where(g=>g.Id is "two" or "tie").Select(g=>g.Id).SequenceEqual(new[]{"two","tie"}),"stable-tie-"+desc);Check(rating[0].Id==(desc?"ten":"two"),"numeric-not-text-"+desc);
  }
  Check(RenameOrder.Ordered(groups,new("natural")).Select(g=>g.Name).SequenceEqual(new[]{"file1.jpg","file2.jpg","file10.jpg","missing.jpg"}),"native-natural-common-names");
  var mixed=new[]{G("text",Input("x.jpg","XMP-test:Value","apple")),G("num",Input("n.jpg","XMP-test:Value","3")),G("date",Input("d.jpg","XMP-test:Value","2024-01-01T00:00:00Z")),G("empty",Input("e.jpg"))};
  Check(RenameOrder.Ordered(mixed,new("metadata",false,"XMP-test:Value")).Select(g=>g.Id).SequenceEqual(new[]{"num","date","text","empty"}),"metadata-numeric-date-text-category");Check(RenameOrder.Ordered(mixed,new("metadata",true,"XMP-test:Value")).Select(g=>g.Id).SequenceEqual(new[]{"text","date","num","empty"}),"metadata-descending-category-missing-last");
  var late=Input("a.xmp","XMP-exif:DateTimeOriginal","2030-01-01T00:00:00Z");var pair=new RenameGroup("pair",[Input("a.jpg","XMP-exif:DateTimeOriginal","2024-01-01T00:00:00Z"),late]);var newer=G("newer",Input("b.jpg","XMP-exif:DateTimeOriginal","2025-01-01T00:00:00Z"));Check(RenameOrder.Ordered([pair,newer,groups[2]],new("shooting",true)).Select(g=>g.Id).SequenceEqual(new[]{"newer","pair","missing"}),"paired-leader-date-not-sidecar");Check(pair.Members.Any(new RenameInputFilter(Extension:"xmp").Matches),"member-hit-includes-group");Check(new RenameInputFilter(From:RenameInput.Date("2024-01-01T00:00:00Z",dates),To:RenameInput.Date("2024-01-01T00:00:00Z",dates)).Matches(pair.Leader),"date-boundaries-inclusive");
  Check(new RenameInputFilter(Tag:"XMP-exif:DateTimeOriginal",Presence:2).Matches(groups[2].Leader),"confirmed-tag-missing");Check(!new RenameInputFilter(Tag:"XMP-exif:DateTimeOriginal",Presence:2).Matches(Input("bad.jpg",failed:true)),"read-failure-not-missing");Check(!new RenameInputFilter(Gps:2).Matches(Input("bad.jpg",failed:true)),"failed-gps-not-absent");
  var full=new[]{"A","hidden","B","C","D"};var visible=new[]{"A","B","C","D"};Check(RenameOrder.Move(new HashSet<string>{"C","D"},"A",visible,full).SequenceEqual(new[]{"C","hidden","D","A","B"}),"shared-filtered-drag-fixture");Check(RenameOrder.Move(new HashSet<string>{"A"},"",visible,full).SequenceEqual(new[]{"B","hidden","C","D","A"}),"end-fills-visible-slots");Check(RenameOrder.Move(new HashSet<string>{"A","C"},"D",visible,full).SequenceEqual(new[]{"B","hidden","A","C","D"}),"noncontiguous-block-order");Check(RenameOrder.Move(new HashSet<string>{"A"},"A",visible,full).SequenceEqual(full),"self-move-no-op");Check(RenameOrder.Move(new HashSet<string>{"hidden"},"A",visible,full).SequenceEqual(full),"hidden-move-rejected");
  var rules="set|photo_\nsequence|1|1|3";var filtered=RenameOrder.Ordered(groups,new("rating")).Where(g=>g.Id!="tie").ToArray();Check(filtered.Select((g,i)=>RenamePlan.Apply(g.Name,RenamePlan.ParseRules(rules),i)).SequenceEqual(new[]{"photo_001.jpg","photo_002.jpg","photo_003.jpg"}),"filter-then-contiguous-numbering");
  var old=RenameRulesPreset.Decode(RenameRulesPreset.Encode(rules,true));Check(old.Order==new RenameOrderSettings("name"),"old-format-readable-name");var modern=RenameRulesPreset.Decode(RenameRulesPreset.Encode(rules,false,new("metadata",true,"XMP-xmp:Rating")));Check(modern.Order==new RenameOrderSettings("metadata",true,"XMP-xmp:Rating")&&modern.Rules==rules,"optional-order-tag-roundtrip");using(var json=JsonDocument.Parse(RenameRulesPreset.Encode(rules,false,new("manual"))))Check(!json.RootElement.TryGetProperty("filter",out _)&&!json.RootElement.TryGetProperty("groups",out _),"no-session-identities-or-filters-in-scheme");
  foreach(var corrupt in new[]{"{\"version\":1,\"rules\":\"upper\",\"sortByName\":false,\"sort\":\"unknown\"}","{\"version\":1,\"rules\":\"upper\",\"sortByName\":false,\"descending\":3}","{\"version\":1,\"rules\":\"upper\",\"sort\":\"manual\"}"}){try{RenameRulesPreset.Decode(corrupt);throw new Exception("corrupt accepted");}catch(ArgumentException){Check(true,"corrupt-scheme-rejected");}}
  foreach(var (sort,tag) in new[]{("make","IFD0:Make"),("model","IFD0:Model"),("city","XMP-photoshop:City"),("created","File:FileCreateDate"),("modified","File:FileModifyDate")})foreach(bool desc in new[]{false,true}){
   bool date=sort is "created" or "modified";var inputs=new[]{G("z",Input("z.jpg",tag,date?"2025-01-01T00:00:00Z":"Z")),G("a",Input("a.jpg",tag,date?"2024-01-01T00:00:00Z":"A")),G("missing",Input("m.jpg"))};var ordered=RenameOrder.Ordered(inputs,new(sort,desc));Check(ordered[0].Id==(desc?"z":"a")&&ordered[^1].Id=="missing","sort-family-date-missing-"+sort+"-"+desc);
  }
  foreach(bool desc in new[]{false,true}){var sized=new[]{G("ten",Input("10.jpg")with{Size=10}),G("two",Input("2.jpg")with{Size=2}),G("missing",Input("m.jpg"))};var ordered=RenameOrder.Ordered(sized,new("size",desc));Check(ordered[0].Id==(desc?"ten":"two")&&ordered[^1].Id=="missing","size-numeric-missing-"+desc);}
  Check(new RenameInputFilter(Query:"file10").Matches(groups[0].Leader)&&new RenameInputFilter(Folder:Path.GetTempPath().TrimEnd(Path.DirectorySeparatorChar)).Matches(groups[0].Leader)&&!new RenameInputFilter(Extension:"dng").Matches(groups[0].Leader),"name-path-directory-type-filter");var located=new RenameInput(Path.Combine(Path.GetTempPath(),"gps.jpg"),new Dictionary<string,string>{{"EXIF:GPSLatitude","0"},{"EXIF:GPSLongitude","0"}});Check(new RenameInputFilter(Gps:1).Matches(located)&&!new RenameInputFilter(Gps:2).Matches(located),"zero-coordinates-are-present");Check(!new RenameInputFilter(From:RenameInput.Date("2024-01-01T00:00:00Z",dates)).Matches(groups[2].Leader),"missing-date-does-not-match-boundary");
  Check(RenameInput.Date("2024-01-01T23:00:00+2300",dates)is null&&RenameInput.Date("2024-01-01T00:00:00+24:00",dates)is null,"shared-offset-boundary-replaces-rename-only-23h-parser");
  var epochMixed=new[]{G("large",Input("n.jpg","XMP-test:Value","2000000000")),mixed[2]};Check(RenameOrder.Ordered(epochMixed,new("metadata",false,"XMP-test:Value"))[0].Id=="date","metadata-date-uses-unix-epoch-like-mac");
  if(Environment.GetEnvironmentVariable("PHOTOTRAIL_RENAME_CONTRACT_FIXTURE")is{} fixture){using var contract=JsonDocument.Parse(File.ReadAllText(fixture));var drag=contract.RootElement.GetProperty("cases").EnumerateArray().Single(c=>c.GetProperty("id").GetString()=="filtered-drag");string[] Strings(string key)=>drag.GetProperty(key).EnumerateArray().Select(v=>v.GetString()!).ToArray();Check(RenameOrder.Move(Strings("moving").ToHashSet(),drag.GetProperty("before").GetString()!,Strings("visible"),Strings("full")).SequenceEqual(Strings("expected")),"fixed-common-json-filtered-drag");var natural=contract.RootElement.GetProperty("cases").EnumerateArray().Single(c=>c.GetProperty("id").GetString()=="natural-filename");var ordered=RenameOrder.Ordered(natural.GetProperty("input").EnumerateArray().Select((v,i)=>G(i.ToString(),Input(v.GetString()!))),new("natural"));Check(ordered.Select(g=>g.Name).SequenceEqual(natural.GetProperty("expected").EnumerateArray().Select(v=>v.GetString()!)),"fixed-common-json-natural");}
  if(Environment.GetEnvironmentVariable("PHOTOTRAIL_RENAME_CONTRACT_FIXTURE")is{} pairFixture){using var contract=JsonDocument.Parse(File.ReadAllText(pairFixture));var pairCase=contract.RootElement.GetProperty("cases").EnumerateArray().Single(c=>c.GetProperty("id").GetString()=="paired-date-descending");var paired=pairCase.GetProperty("input").EnumerateArray().Select(item=>{var input=Input(item.GetProperty("name").GetString()!);return item.TryGetProperty("createdEpoch",out var epoch)?input with{Tags=new Dictionary<string,string>{{"File:FileCreateDate",DateTimeOffset.FromUnixTimeSeconds(epoch.GetInt64()).ToString("yyyy-MM-ddTHH:mm:ssZ")}}}:input;}).GroupBy(i=>RenameGroup.Key(i.Path)).Select(g=>new RenameGroup(g.Key,g.ToArray()));Check(RenameOrder.Ordered(paired,new("created",true)).SelectMany(g=>g.Members).Select(i=>i.Name).SequenceEqual(pairCase.GetProperty("expected").EnumerateArray().Select(v=>v.GetString()!)),"fixed-common-json-paired-date-descending");}
  var absent=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"),"absent.jpg");try{RenamePlan.BuildTargetsAsync(Enumerable.Repeat((absent,"target.jpg"),3001),includeSidecars:false).GetAwaiter().GetResult();throw new Exception("absent accepted");}catch(IOException){Check(true,"explicit-physical-count-preserves-old-6000-limit");}foreach(var count in new[]{3001,6001})try{RenamePlan.BuildTargetsAsync(Enumerable.Repeat((absent,"target.jpg"),count),includeSidecars:count==3001).GetAwaiter().GetResult();throw new Exception("oversize accepted");}catch(ArgumentException){Check(true,"main-or-physical-range-rejected-before-io");}
  Console.WriteLine("RENAME_ORDER_CHECKS="+passed);
 }
}
